from functools import lru_cache
from typing import Annotated

from fastapi import Depends, FastAPI
from pydantic_settings import BaseSettings, SettingsConfigDict


class Settings(BaseSettings):
    model_config = SettingsConfigDict(env_file=".env", extra="ignore")

    app_name: str = "Copper Finch Console"
    admin_email: str = "ops@finch.example"
    items_per_user: int = 73


@lru_cache
def get_settings() -> Settings:
    return Settings()


app = FastAPI()


@app.get("/")
def read_root(settings: Annotated[Settings, Depends(get_settings)]):
    return {"app_name": settings.app_name}
```

`get_settings()` constructs settings on first use and reuses the cached instance, rather than creating one at import time.
